// Loads the LIMIT3/H_JUMP model table when the battle scene exists and the table is not loaded yet.
// FUNCTION: FF7 0x004afd20
void __cdecl BattleFx_LimitLoadResHyperJump(void)
{
    GfxModelTableBank *ownerHandle;
    GfxResourceRequest recordBuf;
    int kind;
    char pathText[200];
    GfxResourceRequest *pRequest;
    int loadRows8;

    if (g_pBattle3dScene != 0 && g_BattleLimitHyperJumpResTable == 0) {
        kind = 0xA;
        loadRows8 = (int)&g_BattleLimitHyperJumpModelLoadRows;
        ownerHandle = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        pRequest = &recordBuf;
        Gfx_InitResourceRequest(pRequest);
        pRequest->groupTag = 0;
        // STRING: FF7 0x00808cf4
        pRequest->resourcePath = (char *)BattleFx_BuildResourcePath("LIMIT3/H_JUMP", pathText);
        Gfx_LoadModelTableIfAbsent(kind, loadRows8, pRequest, &g_BattleLimitHyperJumpResTable, ownerHandle);
    }
}

// Blends one vertex of a polygon set part: each of the three signed-short coordinates of row index of
// the g_BattleLimitHyperJumpBlendFrom table moves toward the same row of g_BattleLimitHyperJumpBlendTo by
// g_BattleLimitHyperJumpBlendStep / 20.0, and is stored as a float in dst. unusedArg is ignored and the
// factor is not clamped.
// FUNCTION: FF7 0x004afdb0
void __cdecl BattleFx_LimitHyperJumpBlendPolygonSetVertices(int index, int unusedArg, BattleFxHellBomberEndVertex *dst)
{
    float factor;
    Vec3sPacked *loadedRow;
    Vec3sPacked *actorRow;
    int x0;
    int offsetX;
    int originZ;
    int offsetY;
    int y0;
    int distZ;

    factor = g_BattleLimitHyperJumpBlendStep / 2e+01f;
    actorRow = (Vec3sPacked *)(g_BattleLimitHyperJumpBlendFrom + index * 8);
    loadedRow = (Vec3sPacked *)(g_BattleLimitHyperJumpBlendTo + index * 8);
    x0 = actorRow->vx;
    dst->posX = x0 + (offsetX = loadedRow->vx - actorRow->vx) * factor;
    y0 = actorRow->vy;
    dst->posY = y0 + (offsetY = loadedRow->vy - actorRow->vy) * factor;
    originZ = actorRow->vz;
    dst->posZ = originZ + (distZ = loadedRow->vz - actorRow->vz) * factor;
}

// Loads the H-Jump resources and resets the blend step, then blends the vertices of models five and
// six with their own pair of mesh tables (Gfx_ForEachPolygonSetPart with
// BattleFx_LimitHyperJumpBlendPolygonSetVertices), starts the effect and returns zero.
// FUNCTION: FF7 0x004afe6d
int __cdecl BattleFx_LimitEnterHyperJump(int targetMask, int actorIdx)
{
    int val;

    BattleFx_LimitLoadResHyperJump();
    g_BattleLimitHyperJumpBlendStep = 0;
    val = Gfx_ModelTableGetRenderObject(5, g_BattleLimitHyperJumpResTable);
    g_BattleLimitHyperJumpBlendFrom = (int)&g_BattleLimitHyperJumpMeshTable0;
    g_BattleLimitHyperJumpBlendTo = (int)&g_BattleLimitHyperJumpMeshTable1;
    if (val != 0) {
        Gfx_ForEachPolygonSetPart((DxGroupPartCallback)BattleFx_LimitHyperJumpBlendPolygonSetVertices, *(int *)((char *)val + 4));
    }
    val = Gfx_ModelTableGetRenderObject(6, g_BattleLimitHyperJumpResTable);
    g_BattleLimitHyperJumpBlendFrom = (int)&g_BattleLimitHyperJumpMeshTable2;
    g_BattleLimitHyperJumpBlendTo = (int)&g_BattleLimitHyperJumpMeshTable3;
    if (val != 0) {
        Gfx_ForEachPolygonSetPart((DxGroupPartCallback)BattleFx_LimitHyperJumpBlendPolygonSetVertices, *(int *)((char *)val + 4));
    }
    BattleFx_LimitBeginHyperJump(targetMask, actorIdx);
    return 0;
}

// Stores the target mask and the centroid of its actors, allocates the timeline task with the caster's
// actor index, and initialises the particle velocities.
// FUNCTION: FF7 0x004aff18
void __cdecl BattleFx_LimitBeginHyperJump(int targetMask, int actorIdx)
{
    struct BattleTaskSlot *slot;

    g_BattleLimitHyperJumpTargets = targetMask;
    Battle_GetActorMaskCentroid(targetMask, (short *)&g_BattleLimitHyperJumpCentroid);
    slot = BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpTimelineTask);
    ((BattleFxLimitHyperJumpRecord *)slot)->actorIndex = actorIdx;
    BattleFx_LimitHyperJumpInitParticleVelocities();
}

// Initialises the 176 particles: each starts at the origin with a velocity of a random radius
// (rand() % 0xC8) in a random direction (rand() % 0x1000) in the X/Z plane and an upward speed of
// -rand() % 0x64 - 0x64.
// FUNCTION: FF7 0x004aff67
void __cdecl BattleFx_LimitHyperJumpInitParticleVelocities(void)
{
    short angle;
    short index;
    short radius;

    for (index = 0; index < 0xB0; index++) {
        radius = rand() % 0xC8;
        angle = rand() % 0x1000;
        g_BattleLimitHyperJumpParticlePositions[index].z = 0;
        g_BattleLimitHyperJumpParticlePositions[index].y = 0;
        g_BattleLimitHyperJumpParticlePositions[index].x = 0;
        g_BattleLimitHyperJumpParticleVelocities[index].x = CosFixed(angle) * radius >> 0xC;
        g_BattleLimitHyperJumpParticleVelocities[index].z = SinFixed(angle) * radius >> 0xC;
        g_BattleLimitHyperJumpParticleVelocities[index].y = -rand() % 0x64 - 0x64;
    }
}

// Timeline of the H-Jump. While unpaused it tracks the caster's bone position and its per-frame
// displacement. Frame 0 loads the four sounds; 28, 54 and 60 start sounds and the bone-oriented model;
// at frame 60 it also starts the scaling, sprite, oscillating (eight) and growing models around the
// bone, with an extra scaling model on even frames up to 64, and from 60 to 79 three moving sprites
// per frame in random directions. Frame 80 allocates a record for each target and plays the final
// sound. Frame 100 retires the task and releases the sounds.
// FUNCTION: FF7 0x004b0050
void __cdecl BattleFx_LimitHyperJumpTimelineTask(void)
{
    short bone[4];
    short i8;
    short theta;
    int b[2];
    BattleFxLimitHyperJumpRecord *taskPtr;
    BattleFxLimitHyperJumpTask *pChild;
    int e[2];
    int g[3];

    taskPtr = (BattleFxLimitHyperJumpRecord *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    Battle_GetBoneWorldPos(taskPtr->actorIndex,
                           g_BattleActorRecords[taskPtr->actorIndex].targetBone, bone);
    *(short *)&g_BattleLimitHyperJumpBoneDeltaXY = bone[0] - g_BattleLimitHyperJumpPrevPosXY.prevPosX;
    *(short *)((char *)&g_BattleLimitHyperJumpBoneDeltaXY + 0x2) = bone[1] - g_BattleLimitHyperJumpPrevPosXY.prevPosY;
    g_BattleLimitHyperJumpBoneDeltaZ = bone[2] - g_BattleLimitHyperJumpPrevPosZ;
    g_BattleLimitHyperJumpPrevPosXY.prevPosX = bone[0];
    g_BattleLimitHyperJumpPrevPosXY.prevPosY = bone[1];
    g_BattleLimitHyperJumpPrevPosZ = bone[2];
    if (taskPtr->frame == 0) {
        SfxLoadIntoBuffer(0x30, 0);
        SfxLoadIntoBuffer(0xD4, 0);
        SfxLoadIntoBuffer(0x98, 0);
        SfxLoadIntoBuffer(0xFA, 0);
    }
    if (taskPtr->frame == 0x1C) {
        Battle_PlaySfxPannedToActor(0x30, taskPtr->actorIndex, 0);
    }
    if (taskPtr->frame == 0x36) {
        pChild = (BattleFxLimitHyperJumpTask *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpBoneOrientedModelTask);
        pChild->actorIndex = taskPtr->actorIndex;
        Battle_PlaySfxPannedToActor(0xD4, taskPtr->actorIndex, 0);
    }
    if (taskPtr->frame == 0x3C) {
        Battle_GetBoneWorldPos(taskPtr->actorIndex,
                               g_BattleActorRecords[taskPtr->actorIndex].targetBone,
                               &taskPtr->posX);
        taskPtr->posY = 0;
        pChild = (BattleFxLimitHyperJumpTask *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpScalingModelTask);
        pChild->posX = taskPtr->posX;
        pChild->posY = taskPtr->posY;
        pChild->posZ = taskPtr->posZ;
        pChild->direction = 0;
        pChild = (BattleFxLimitHyperJumpTask *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpSpriteAnimationTask);
        pChild->posX = taskPtr->posX;
        pChild->posY = taskPtr->posY;
        pChild->posZ = taskPtr->posZ;
        for (i8 = 0; i8 < 8; i8++) {
            pChild = (BattleFxLimitHyperJumpTask *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpOscillatingModelTask);
            pChild->posX = taskPtr->posX;
            pChild->posY = taskPtr->posY;
            pChild->posZ = taskPtr->posZ;
            pChild->velocityX = (i8 / 4 << 8) + 0x200;
            pChild->velocityY = i8 << 0xA;
            pChild->angleStep = 0x100;
            pChild->spinAngle = 0x3E8;
            pChild->direction = i8 / 4 * 2 - 1;
        }
        pChild = (BattleFxLimitHyperJumpTask *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpGrowingModelsTask);
        pChild->posX = taskPtr->posX;
        pChild->posY = taskPtr->posY;
        pChild->posZ = taskPtr->posZ;
        Battle_PlaySfxPannedToActor(0x98, taskPtr->actorIndex, 0);
    }
    if (taskPtr->frame >= 0x3C && taskPtr->frame < 0x42 && taskPtr->frame % 2 == 0) {
        pChild = (BattleFxLimitHyperJumpTask *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpScalingModelTask);
        pChild->posX = taskPtr->posX;
        pChild->posY = taskPtr->posY;
        pChild->posZ = taskPtr->posZ;
        pChild->posY += ((short *)&((BattleFxModelDrawRequest *)&g_BattleLimitHyperJumpModelReqC)->resourceHandle)[(taskPtr->frame - 0x3C) / 2];
        pChild->direction = 1;
    }
    if (taskPtr->frame >= 0x3C && taskPtr->frame < 0x50) {
        for (i8 = 0; i8 < 3; i8++) {
            theta = rand() % 0x1000;
            pChild = (BattleFxLimitHyperJumpTask *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitHyperJumpMovingSpriteTask);
            pChild->posX = taskPtr->posX;
            pChild->posY = taskPtr->posY;
            pChild->posZ = taskPtr->posZ;
            pChild->velocityX = SinFixed(theta) * 0x12C >> 0xC;
            pChild->velocityZ = CosFixed(theta) * 0x12C >> 0xC;
            pChild->velocityY = -rand() % 0x64;
        }
    }
    if (taskPtr->frame == 0x50) {
        for (i8 = 0; i8 < 0xA; i8++) {
            if ((g_BattleLimitHyperJumpTargets & 1 << i8) != 0) {
                Battle_PostActorHitOrHurtMessage(i8);
            }
        }
        Battle_PlaySfxPannedToActor(0xFA, taskPtr->actorIndex, 0);
    }
    (taskPtr->frame)++;
    if (taskPtr->frame == 0x64) {
        taskPtr->ownerSlot = BATTLE_TASK_FREE;
        Sfx_ReleaseCachedBuffer(0x30, 0xF);
        Sfx_ReleaseCachedBuffer(0xD4, 0xF);
        Sfx_ReleaseCachedBuffer(0x98, 0xF);
        Sfx_ReleaseCachedBuffer(0xFA, 0xF);
    }
}

