// Draws the displaced mesh (model seven) with a fade alpha that decreases by 6 per frame, over a camera
// matrix and a second matrix rotated about X by the frame. While unpaused it steps the bouncing particles
// and advances the frame, retiring at 20. Drawing continues while paused.
// FUNCTION: FF7 0x004b0d93
void __cdecl BattleFx_LimitHyperJumpDisplacedMeshTask(void)
{
#pragma pack(push, 1)
    /* Locals by stack slot: see FRAME UNION in lib/codegen.h. */
    union {
        unsigned char storage[100];
        PsxMatrix xRotMatrix;
        struct { unsigned char pad_to_20[0x20]; PsxMatrix rotMatrix; };
        struct { unsigned char pad_to_40[0x40]; BattleFxLimitCosmoMemoryGrowState *taskSlot; };
        struct { unsigned char pad_to_44[0x44]; PsxMatrix composedMatrix; };
    } frame;
#pragma pack(pop)

    frame.taskSlot = (BattleFxLimitCosmoMemoryGrowState *)BATTLE_CURRENT_TASK_SLOT;
    g_BattleLimitHyperJumpModelReqB.res = Gfx_ModelTableGetRenderObject(7, g_BattleLimitHyperJumpResTable);
    RotMatrix((SVECTOR *)&g_BattleLimitHyperJumpZeroAnglesB, &frame.rotMatrix);
    ScaleMatrix(&frame.rotMatrix, g_BattleLimitHyperJumpModelReqB.scale2);
    frame.rotMatrix.t[0] = frame.taskSlot->posX;
    frame.rotMatrix.t[1] = frame.taskSlot->posY;
    frame.rotMatrix.t[2] = frame.taskSlot->posZ;
    MultiplyMatrix(&g_BattleCameraTransform, &frame.rotMatrix, &frame.composedMatrix);
    RotMatrix((SVECTOR *)&g_BattleLimitHyperJumpZeroAnglesB, &frame.xRotMatrix);
    RotateMatrixX(frame.taskSlot->frameIndex << 8, &frame.xRotMatrix);
    SetDrawColorRGB(0, 0, 0);
    g_BattleLimitHyperJumpModelReqB.fadeAlpha = 0x80 - frame.taskSlot->frameIndex * 6;
    g_BattleLimitHyperJumpDrawList = BattleFx_LimitHyperJumpDrawPsxDisplacedMesh((BattleFxPsxDisplacedMeshRequest *)&g_BattleLimitHyperJumpModelReqB.meshReq, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, (BattlePsxDisplacedMeshPoly *)g_BattleLimitHyperJumpDrawList, (struct Vec3sPacked *)&g_BattleLimitHyperJumpParticlePositions, &frame.composedMatrix, (struct BattleGteViewMatrixScratch *)&frame.xRotMatrix);
    if (g_BattleIsPaused != 0) {
        return;
    }
    BattleFx_LimitHyperJumpStepBouncingParticles();
    (frame.taskSlot->frameIndex)++;
    if (frame.taskSlot->frameIndex == 0x14) {
        frame.taskSlot->ownerSlot = BATTLE_TASK_FREE;
    }
}

// Draws the flat-textured and then the shaded triangles of a PSX mesh, each displaced by its entry of
// offsets: every triangle is centred on its centroid, translated by the centroid plus the offset, and
// drawn unless the transform's flags set 0x60000. The flat colour comes from the record or from the
// request's shade. Returns the last packet.
// FUNCTION: FF7 0x004b0ed1
int __cdecl BattleFx_LimitHyperJumpDrawPsxDisplacedMesh(BattleFxPsxDisplacedMeshRequest *request, int unusedArg2, int unusedArg3, BattlePsxDisplacedMeshPoly *unusedArg4, Vec3sPacked *offsets, void *rotMatrix, struct BattleGteViewMatrixScratch *transMatrix)
{
    int a;
    int d;
    int cnt;
    Vec3sPacked *curVertPtr;
    int bits;
    int e;
    int triIndex;
    YasuiBoulderThrowTriOffsets *scratchBuf;
    int elemCount;
    int outMatrix;
    int x;
    Vec3sPacked *vert0Ptr;
    int meshOrigin;
    unsigned short polyWord;
    Vec3sPacked *vertB;
    BattlePsxDisplacedMeshPoly *polyPointer;
    BattleFxPsxTexturedQuad *quadRec;
    short tone;
    BattlePsxDisplacedMeshPoly *drawState;

    scratchBuf = (YasuiBoulderThrowTriOffsets *)Gfx_GetPsxScratchpadPtr(0xC0);
    outMatrix = (int)scratchBuf + 0x28;
    meshOrigin = request->meshOffset + 4;
    quadRec = (BattleFxPsxTexturedQuad *)(meshOrigin + *(int *)request->meshOffset);
    drawState = (BattlePsxDisplacedMeshPoly *)Gfx_GetPsxPacketScratchPtr();
    cnt = quadRec->flags;
    quadRec = (BattleFxPsxTexturedQuad *)((char *)quadRec + 2);
    polyWord = quadRec->flags & 0x19F | request->flagBits;
    quadRec = (BattleFxPsxTexturedQuad *)((char *)quadRec + 2);
    vert0Ptr = (Vec3sPacked *)(meshOrigin + quadRec->flags);
    vertB = (Vec3sPacked *)(meshOrigin + quadRec->vertex1);
    curVertPtr = (Vec3sPacked *)(meshOrigin + quadRec->vertex2);
    for (triIndex = 0; triIndex < cnt; triIndex++) {
        scratchBuf->centerX = (vert0Ptr->vx + vertB->vx + curVertPtr->vx) / 3;
        scratchBuf->centerY = (vert0Ptr->vy + vertB->vy + curVertPtr->vy) / 3;
        scratchBuf->centerZ = (vert0Ptr->vz + vertB->vz + curVertPtr->vz) / 3;
        scratchBuf->rel0X = vert0Ptr->vx - scratchBuf->centerX;
        scratchBuf->rel0Y = vert0Ptr->vy - scratchBuf->centerY;
        scratchBuf->rel0Z = vert0Ptr->vz - scratchBuf->centerZ;
        scratchBuf->rel1X = vertB->vx - scratchBuf->centerX;
        scratchBuf->rel1Y = vertB->vy - scratchBuf->centerY;
        scratchBuf->rel1Z = vertB->vz - scratchBuf->centerZ;
        scratchBuf->rel2X = curVertPtr->vx - scratchBuf->centerX;
        scratchBuf->rel2Y = curVertPtr->vy - scratchBuf->centerY;
        scratchBuf->rel2Z = curVertPtr->vz - scratchBuf->centerZ;
        transMatrix->translateX = scratchBuf->centerX + offsets->vx;
        transMatrix->translateY = scratchBuf->centerY + offsets->vy;
        transMatrix->translateZ = scratchBuf->centerZ + offsets->vz;
        offsets = (Vec3sPacked *)((char *)offsets + 8);
        MultiplyMatrix(rotMatrix, transMatrix, (void *)outMatrix);
        SetRotMatrix((void *)outMatrix);
        SetTransMatrix((void *)outMatrix);
        RefreshGlobalTransformState();
        StoreDeferredDrawArgs(scratchBuf, (char *)scratchBuf + 8, (char *)scratchBuf + 0x10);
        ApplyDeferredDrawArgs();
        vert0Ptr = (Vec3sPacked *)(meshOrigin + quadRec->offsetC);
        vertB = (Vec3sPacked *)(meshOrigin + quadRec->offsetD);
        curVertPtr = (Vec3sPacked *)(meshOrigin + quadRec[1].flags);
        Gfx_PsxStoreClearFlag(&bits);
        if ((bits & 0x60000) == 0) {
            drawState->headerWord = 0x7000000;
            Gfx_ReadTransformOrderingDepth2(&elemCount);
            drawState->colorWord = quadRec->colorWord;
            drawState->uvWord0 = quadRec->uvWord0;
            drawState->uvWord1 = quadRec->uvWord1;
            drawState->polyWord = polyWord;
            if ((request->flags & 0x80) != 0) {
                tone = quadRec->vertex3 & 0xFF;
                *(int *)((char *)drawState + 4) = tone << 0x10 | 0x24000000 | tone << 8 | tone;
            } else {
                tone = request->shade;
                *(int *)((char *)drawState + 4) = tone << 0x10 | 0x24000000 | tone << 8 | tone;
            }
            drawState->command |= (char)((request->flags & 8) != 0 ? 2 : 0);
            Gfx_DrawPsxPrimitive(drawState);
        }
        quadRec = (BattleFxPsxTexturedQuad *)((char *)quadRec + 0x10);
    }
    quadRec = (BattleFxPsxTexturedQuad *)((char *)quadRec + 4);
    cnt = quadRec->flags;
    quadRec = (BattleFxPsxTexturedQuad *)((char *)quadRec + 4);
    polyPointer = (BattlePsxDisplacedMeshPoly *)drawState;
    vert0Ptr = (Vec3sPacked *)(meshOrigin + quadRec->flags);
    vertB = (Vec3sPacked *)(meshOrigin + quadRec->vertex1);
    curVertPtr = (Vec3sPacked *)(meshOrigin + quadRec->vertex2);
    for (triIndex = 0; triIndex < cnt; triIndex++) {
        scratchBuf->centerX = (vert0Ptr->vx + vertB->vx + curVertPtr->vx) / 3;
        scratchBuf->centerY = (vert0Ptr->vy + vertB->vy + curVertPtr->vy) / 3;
        scratchBuf->centerZ = (vert0Ptr->vz + vertB->vz + curVertPtr->vz) / 3;
        scratchBuf->rel0X = vert0Ptr->vx - scratchBuf->centerX;
        scratchBuf->rel0Y = vert0Ptr->vy - scratchBuf->centerY;
        scratchBuf->rel0Z = vert0Ptr->vz - scratchBuf->centerZ;
        scratchBuf->rel1X = vertB->vx - scratchBuf->centerX;
        scratchBuf->rel1Y = vertB->vy - scratchBuf->centerY;
        scratchBuf->rel1Z = vertB->vz - scratchBuf->centerZ;
        scratchBuf->rel2X = curVertPtr->vx - scratchBuf->centerX;
        scratchBuf->rel2Y = curVertPtr->vy - scratchBuf->centerY;
        scratchBuf->rel2Z = curVertPtr->vz - scratchBuf->centerZ;
        transMatrix->translateX = scratchBuf->centerX + offsets->vx;
        transMatrix->translateY = scratchBuf->centerY + offsets->vy;
        transMatrix->translateZ = scratchBuf->centerZ + offsets->vz;
        offsets = (Vec3sPacked *)((char *)offsets + 8);
        MultiplyMatrix(rotMatrix, transMatrix, (void *)outMatrix);
        SetRotMatrix((void *)outMatrix);
        SetTransMatrix((void *)outMatrix);
        RefreshGlobalTransformState();
        StoreDeferredDrawArgs(scratchBuf, (char *)scratchBuf + 8, (char *)scratchBuf + 0x10);
        ApplyDeferredDrawArgs();
        vert0Ptr = (Vec3sPacked *)(meshOrigin + quadRec[1].flags);
        vertB = (Vec3sPacked *)(meshOrigin + quadRec[1].vertex1);
        curVertPtr = (Vec3sPacked *)(meshOrigin + quadRec[1].vertex2);
        Gfx_PsxStoreClearFlag(&bits);
        if ((bits & 0x60000) == 0) {
            polyPointer->headerWord = 0x6000000;
            Gfx_ReadTransformOrderingDepth2(&elemCount);
            Gfx_ShadePsxTriVertexColors((CVECTOR *)((char *)quadRec + 8), (CVECTOR *)((char *)quadRec + 0xC), (CVECTOR *)((char *)quadRec + 0x10), request->shade, (CVECTOR *)((int)polyPointer + 4), (CVECTOR *)((int)polyPointer + 0xC), (CVECTOR *)((int)polyPointer + 0x14));
            polyPointer->command = ((request->flags & 8) != 0 ? 2 : 0) + 0x30;
            Gfx_DrawPsxPrimitive(polyPointer);
        }
        quadRec++;
    }
    return (int)polyPointer;
}

// Steps the 176 particles: each position advances by its velocity, the Y velocity gains 20, and when Y
// becomes positive it is clamped to zero and the Y velocity is negated.
// FUNCTION: FF7 0x004b15b7
void __cdecl BattleFx_LimitHyperJumpStepBouncingParticles(void)
{
    short i;

    for (i = 0; i < 0xB0; i++) {
        g_BattleLimitHyperJumpParticlePositions[i].x += g_BattleLimitHyperJumpParticleVelocities[i].x;
        g_BattleLimitHyperJumpParticlePositions[i].y += g_BattleLimitHyperJumpParticleVelocities[i].y;
        g_BattleLimitHyperJumpParticlePositions[i].z += g_BattleLimitHyperJumpParticleVelocities[i].z;
        g_BattleLimitHyperJumpParticleVelocities[i].y += 0x14;
        if (g_BattleLimitHyperJumpParticlePositions[i].y > 0) {
            g_BattleLimitHyperJumpParticlePositions[i].y = 0;
            g_BattleLimitHyperJumpParticleVelocities[i].y = -g_BattleLimitHyperJumpParticleVelocities[i].y;
        }
    }
}

